strings:
body,
html {
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    margin-left: auto;
    margin-right: auto;
}

.centered-div {
    text-align: center;
}

#status {
    font-variant-numeric: tabular-nums;
}

#progress {
    display: none;
    width: 90%;
    width: min(20rem, 90%);
    height: 2rem;
    border-radius: 1rem;
    overflow: hidden;
    margin: 1rem 0 2rem;
    outline-offset: 2px;
    outline: #b16286 solid 4px;
}

.bar-inner {
    background-color: #b16286;
    height: 100%;
    width: 0;
    transition: width 0.25s ease-in;
}
